function mmParse(text){
  if(typeof text!=='string'||!text.trim()) return { value:null, error:'大纲为空' };
  var lines=text.split('\n').filter(function(l){ return l.trim()!==''; });
  var items=[];
  for(var i=0;i<lines.length;i++){
    var raw=lines[i].replace(/\t/g,'  ');
    var m=raw.match(/^( *)(.*)$/);
    var depth=Math.floor(m[1].length/2);
    items.push({ depth:depth, label:m[2].trim() });
  }
  if(items[0].depth!==0) return { value:null, error:'首行必须无缩进（中心主题）' };
  for(var j=1;j<items.length;j++){
    if(items[j].depth===0) return { value:null, error:'第 '+(j+1)+' 行: 只允许一个中心主题' };
    if(items[j].depth>items[j-1].depth+1) return { value:null, error:'第 '+(j+1)+' 行: 缩进跳级' };
  }
  var root={ label:items[0].label, children:[] };
  var stack=[root];
  for(var k=1;k<items.length;k++){
    var node={ label:items[k].label, children:[] };
    stack.length=items[k].depth;
    stack[stack.length-1].children.push(node);
    stack.push(node);
  }
  return { value:root, error:null };
}
function mmCountLeaves(node){
  if(!node.children.length) return 1;
  var s=0;
  for(var i=0;i<node.children.length;i++) s+=mmCountLeaves(node.children[i]);
  return s;
}
function mmLayout(root){
  var nodes=[], edges=[], ROW=34, COL=170;
  function place(node, depth, top){
    var leaves=mmCountLeaves(node);
    var y=top+leaves*ROW/2;
    var me={ label:node.label, x:depth*COL+20, y:y, depth:depth };
    nodes.push(me);
    var cur=top;
    for(var i=0;i<node.children.length;i++){
      var child=place(node.children[i], depth+1, cur);
      edges.push({ x1:me.x, y1:me.y, x2:child.x, y2:child.y });
      cur+=mmCountLeaves(node.children[i])*ROW;
    }
    return me;
  }
  place(root, 0, 0);
  var w=0,h=0;
  for(var i=0;i<nodes.length;i++){
    if(nodes[i].x>w) w=nodes[i].x;
    if(nodes[i].y>h) h=nodes[i].y;
  }
  return { nodes:nodes, edges:edges, width:w+180, height:h+40 };
}
function mmEsc(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function mmSvg(text){
  var p=mmParse(text);
  if(p.error) return { value:null, error:p.error };
  var L=mmLayout(p.value);
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+L.width+'" height="'+L.height+'" viewBox="0 0 '+L.width+' '+L.height+'">';
  s+='<rect width="'+L.width+'" height="'+L.height+'" fill="#0A0A0B"/>';
  for(var i=0;i<L.edges.length;i++){
    var e=L.edges[i], mx=(e.x1+e.x2)/2;
    s+='<path d="M'+(e.x1+120)+' '+e.y1+' C'+mx+' '+e.y1+' '+mx+' '+e.y2+' '+e.x2+' '+e.y2+'" fill="none" stroke="rgba(94,106,210,0.55)" stroke-width="1.5"/>';
  }
  var PAL=['#5E6AD2','#22D3EE','#10B981','#A78BFA','#F5A623'];
  for(var j=0;j<L.nodes.length;j++){
    var n=L.nodes[j], c=PAL[n.depth%PAL.length];
    s+='<rect x="'+n.x+'" y="'+(n.y-13)+'" width="120" height="26" rx="7" fill="#141417" stroke="'+c+'" stroke-width="1.2"/>';
    s+='<text x="'+(n.x+60)+'" y="'+(n.y+4)+'" text-anchor="middle" font-size="12" fill="#FFFFFF" font-family="system-ui,sans-serif">'+mmEsc(n.label.length>9?n.label.slice(0,8)+'…':n.label)+'</text>';
  }
  s+='</svg>';
  return { value:s, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { mmParse:mmParse, mmCountLeaves:mmCountLeaves, mmLayout:mmLayout, mmSvg:mmSvg, mmEsc:mmEsc };
}
if (typeof window !== 'undefined') {
  window.MindMapForgePure = { mmParse:mmParse, mmCountLeaves:mmCountLeaves, mmLayout:mmLayout, mmSvg:mmSvg, mmEsc:mmEsc };
}
